        bs=bars(row,False)
        for i,(a,b) in enumerate(bs[:-1]):
            nxt=bs[i+1][0] if i+1<len(bs) else W
            if a<b<nxt and inp[r][a]==inp[r][b]:
                for g in range(a+1,nxt): out[r][g]=inp[r][a]
