        opts=[]
        for c in range(W):
            if inp[r][c]!=0: opts.append((abs(c-g),inp[r][c],c))
        opts.sort()
        return opts[0][1] if opts else None
    fr=[r for r in range(H) if any(v!=0 for v in inp[r])]
