# Hypothesis A: vertical fill of gap columns by segment color = color of nearest nonzero cell BELOW in that column (anchor), top segment = first anchor's color.
def fA(inp):
    H,W=len(inp),len(inp[0])
    out=[r[:] for r in inp]
    # horizontal gap fill: consecutive equal-color blocks with a hole
    for r in range(H):
        row=inp[r]
        s=None
        for c,v in enumerate(row):
            if v!=0:
                if s is None: s=c
                elif c>s+1: 
                    for g in range(s+1,c): out[r][g]=row[s]
            else:
                if s is not None: s=None
    # gap columns: columns where a row had a horizontal gap filled (cell was 0 between two equal colors)
    gc=set()
    for r in range(H):
        row=inp[r]
        s=None
        for c,v in enumerate(row):
            if v!=0:
                if s is None: s=c
                elif c>s+1:
                    for g in range(s+1,c): gc.add(g)
            else:
                if s is not None: s=None
        if s is not None: gc.add(W-1)  # trailing? ignore
    # anchors per gap column: rows where column is nonzero in INPUT (after horizontal fill)
    def anchors(g):
        return [(r,inp[r][g]) for r in range(H) if inp[r][g]!=0]
    anch={}
    for g in gc: anc=anchors(g); anch[g]=sorted(set((r,v) for r,v in anc))
    for g,a in anch.items():
        rows=[r for r,_ in a]
        lo,hi=rows[0],rows[-1]
        for r in range(lo,hi+1):
            out[r][g]=a[0][1] if r==lo else a[-1][1]
    return out
